<?php
/** TEMP PS S1688 mm — v0.6: f=laukai — Sender laukai PS_HERO_G2 („200–220 g"), PS_HERO_D2 („54–60"), PS_HERO_PAK („12 kg maišo") + terra 23 laukai vienu PATCH; logo_url. f=kurti — 3 testinės kampanijos v0.6 (__LOGO__ → Petshop_Email_Layout::logo_url()) į PS_TEST. */
add_action('init', function(){
  if (!isset($_GET['ps_s1688mm'])) return; global $wpdb; $o=array('v'=>'S1688 mm'); $f=$_GET['ps_s1688mm']; $t=Petshop_Relaunch::t();
  $tok=Petshop_Sender_Adapter::get_stored_token('marketing'); $logo=class_exists('Petshop_Email_Layout')?Petshop_Email_Layout::logo_url():''; $o['logo']=$logo;
  $api=function($m,$p,$b=null) use($tok){ $a=array('method'=>$m,'timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.$tok,'Accept'=>'application/json','Content-Type'=>'application/json')); if($b!==null) $a['body']=wp_json_encode($b);
    $r=wp_remote_request('https://api.sender.net/v2'.$p,$a); if(is_wp_error($r)) return array('code'=>0,'err'=>$r->get_error_message()); return array('code'=>wp_remote_retrieve_response_code($r),'body'=>json_decode(wp_remote_retrieve_body($r),true)); };
  if($f==='laukai'){
    $r=$api('GET','/fields?limit=100'); $yra=array(); foreach((array)($r['body']['data']??array()) as $x) $yra[$x['title']]=1;
    foreach(array('PS_HERO_G2','PS_HERO_D2','PS_HERO_PAK') as $l){ $o[$l]=isset($yra[$l])?'buvo':$api('POST','/fields',array('title'=>$l,'type'=>'text'))['code']; }
    $row=$wpdb->get_row("SELECT * FROM $t WHERE email='terra@gyvunai.lt'",ARRAY_A); $duom=json_decode($row['duomenys'],true); $up=wp_upload_dir(); $pr=wc_get_product(12466);
    $pak='Pakuotės'; if(preg_match('/(\d+(?:[,.]\d+)?)\s?kg/iu',$pr->get_name(),$m)) $pak=str_replace('.',',',$m[1]).' kg maišo'; elseif($pr->get_weight()) $pak=str_replace('.',',',(string)(float)$pr->get_weight()).' kg maišo';
    $fl=array('PS_HERO_SEG'=>'calc','PS_HERO_PAV'=>$duom['pav'],'PS_HERO_KAINA'=>number_format((float)$duom['kaina'],2,',','').' €','PS_HERO_IMG'=>$up['baseurl'].'/ps-relaunch/12466.jpg','PS_HERO_URL'=>$duom['url'],'PS_HERO_GYV'=>'šuniui','PS_HERO_ANTR'=>'Jūsų pamėgtos prekės','PS_HERO_KODEL'=>'nes esate pirkę petshop.lt','PS_HERO_PAK'=>$pak);
    foreach($duom['eilutes'] as $i=>$e){ $n=$i+1; $fl["PS_HERO_KG$n"]=$e['kg'].' kg'; $fl["PS_HERO_EUR$n"]='nuo '.$e['eur_nuo'].' €'; $fl["PS_HERO_INFO$n"]=$e['g'].' g/d · maišo užtenka '.$e['d'].' d.'; $fl["PS_HERO_U$n"]=$e['url']; if($n===2){ $fl['PS_HERO_G2']=$e['g'].' g'; $fl['PS_HERO_D2']=$e['d']; } }
    $p=$api('PATCH','/subscribers/terra%40gyvunai.lt',array('fields'=>$fl)); $o['patch']=$p['code']; $g=$api('GET','/subscribers/terra%40gyvunai.lt'); $o['cols_n']=count($g['body']['data']['columns']??array()); $o['pak']=$pak;
  } else {
    $K=array(
      'calc'=>array('t'=>'TEST relaunch CALC v0.6','s'=>'{{ps_hero_kg2}} {{ps_hero_gyv}} – {{ps_hero_eur2}} per dieną?','p'=>'Apskaičiavome pagal maistą, kurį anksčiau rinkotės. O kiek sveria jūsų augintinis?','h'=>''),
      'product'=>array('t'=>'TEST relaunch PRODUCT v0.6','s'=>'{{ ps_hero_antr | default: "Pažįstamos prekės" }} – atnaujintame Petshop.lt','p'=>'{{ps_hero_pav}} – turime, {{ps_hero_kaina}}. Užsakymų istorija išsaugota, prisijungimas be slaptažodžio.','h'=>''),
      'generic'=>array('t'=>'TEST relaunch GENERIC v0.6','s'=>'Petshop.lt atsinaujino – kas pasikeitė jūsų pirkiniams','p'=>'Ta pati parduotuvė nuo 2010 m., nauja svetainė, jūsų užsakymų istorija išsaugota.','h'=>''));
    $g=$api('GET','/groups/bDxp2q')['body']['data']??array(); $o['aktyviu']=$g['active_subscribers']??null;
    foreach($K as $k=>$c){ $html=str_replace('__LOGO__',$logo,base64_decode($c['h'])); $b=array('title'=>$c['t'].' '.date('H:i'),'subject'=>$c['s'],'from'=>'Petshop.lt','reply_to'=>'terra@petshop.lt','content_type'=>'html','content'=>$html,'groups'=>array('bDxp2q'),'preheader'=>$c['p']);
      $r=$api('POST','/campaigns',$b); $id=$r['body']['data']['id']??''; $o[$k]=array('kurti'=>$r['code'],'id'=>$id,'err'=>$r['body']['errors']??null);
      if($id && (int)($g['active_subscribers']??0)===1){ $s=$api('POST','/campaigns/'.$id.'/send'); $o[$k]['send']=$s['code'].' '.wp_json_encode($s['body']['message']??$s['body']); } }
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
